import React from 'react';

import A4Page from '@components/A4Page';
import MapWithElevation from '@components/MapWithElevation';
import Page from '@components/Page';
import PageHeader from '@components/PageHeader';
import PageLoader from '@components/PageLoader';
import PolylineInfo from '@components/PolylineInfo';
import { formatAltitude, formatDistance } from '@helpers/formatHelper';
import { round } from '@helpers/mathHelper';
import Breadcrumb from '@ui-kit/Breadcrumb';
import PohButton, { ButtonVariant } from '@ui-kit/Button';
import PohContainer from '@ui-kit/layout/Container';

import { getBaseRouteDataAsync, getRouteObjectsAsync } from '../../Routes/@services/routes.service';
import { IMapType, IRouteObject, RouteObjectType } from '../../Routes/@types/routes.types';
import { getHikingDataAsync } from '../@services/hiking.service';
import { getHikingSchedule } from '../@services/hikingSchedule.service';
import { IHikingScheduleItem } from '../@types/hiking.baseTypes';
import { IHikingData } from '../@types/hiking.types';

interface IHikingRouteInfoPageProps {
  id_hiking: number;
  id_route: number;
  search?: string;
}

const HikingRouteInfoPage: React.FC<IHikingRouteInfoPageProps> = ({ id_hiking, id_route }) => {
  const [hikingData, setHikingData] = React.useState<IHikingData | null>(null);
  const [mapType, setMapType] = React.useState<IMapType | null>(null);
  const [schedules, setSchedules] = React.useState<IHikingScheduleItem[]>([]);
  const [routeObjects, setRouteObjects] = React.useState<IRouteObject[]>([]);
  const [isLoading, setIsLoading] = React.useState(true);

  React.useEffect(() => {
    const start = async () => {
      await getHikingDataAsync(id_hiking).then(setHikingData);
      await getHikingSchedule(id_hiking).then(setSchedules);
      await getRouteObjectsAsync(id_route).then(setRouteObjects);
      const { typeData } = await getBaseRouteDataAsync(id_route);
      setMapType(typeData);
    };

    start().finally(() => setIsLoading(false));
  }, [id_hiking, id_route]);

  if (isLoading) {
    return <PageLoader />;
  }

  if (!hikingData) {
    return null;
  }
  if (!mapType) {
    return null;
  }
  return (
    <Page title={`Передвижения похода «${hikingData.name}»`}>
      <PohContainer>
        <div className="d-print-none">
          <Breadcrumb
            data={[
              { href: '/hiking', text: 'Походы' },
              { href: `/hiking/${id_hiking}`, text: hikingData.name ?? '' },
              {
                href: `/hiking/${id_hiking}/hiking_route_info/${id_route}`,
                text: 'Передвижения',
                active: true,
              },
            ]}
          />
        </div>
        <PageHeader title={`Передвижения похода «${hikingData.name}»`} className="d-print-none">
          <PohButton onClick={() => window.print()} variant={ButtonVariant.Light}>
            Печать
          </PohButton>
        </PageHeader>

        {schedules
          .filter((s) => s.routeObject)
          .map((schedule) => {
            const routeObject = routeObjects.find((ro) => ro.id === schedule.routeObject?.id);
            if (!routeObject || routeObject.type !== RouteObjectType.Line) return null;
            const diffMs = schedule.finish.getTime() - schedule.start.getTime();
            const diff = new Date(diffMs + new Date().getTimezoneOffset() * 60000);
            const speedKmH = routeObject.distance / 1000 / (diffMs / 1000 / 60 / 60);

            const heights = routeObject.points.filter((p) => !!p[2]).map((p) => p[2]) as number[];
            const maxH = Math.ceil(Math.max(...heights));
            const minH = Math.floor(Math.min(...heights));

            return (
              <A4Page key={routeObject.id}>
                <h4>
                  <small className="float-end label label-info">
                    {formatDistance(routeObject.distance)}
                  </small>
                  {schedule.name}
                </h4>
                <section>
                  <div>
                    <div>
                      <strong>{routeObject.name}</strong>. &nbsp;
                      <strong>
                        {schedule.start.toLocaleDateString()}
                        &nbsp;
                        <sup>
                          {schedule.start.toLocaleTimeString(undefined, { timeStyle: 'short' })}
                        </sup>
                        &thinsp;-&thinsp;
                        <sub>
                          {schedule.finish.toLocaleTimeString(undefined, { timeStyle: 'short' })}
                        </sub>
                        .
                      </strong>
                      <span>
                        {' '}
                        (в пути {diff.toLocaleTimeString(undefined, { timeStyle: 'short' })})
                      </span>
                      <span>
                        {' '}
                        V<sub>ср.план </sub>
                        {round(speedKmH)} км/ч;
                      </span>
                      &nbsp; &nbsp;
                      <span>
                        H⭳: <strong>{formatAltitude(minH)}</strong>; H⭱:{' '}
                        <strong>{formatAltitude(maxH)}</strong>; H⭿:{' '}
                        <strong>{formatAltitude(maxH - minH)}</strong>;
                      </span>
                    </div>
                  </div>
                  <div>
                    {location.hash ? (
                      <MapWithElevation
                        points={routeObject.points}
                        mapType={mapType}
                        height={900}
                        slope
                      />
                    ) : (
                      <PolylineInfo
                        points={routeObject.points}
                        name={routeObject.name}
                        poi={routeObjects.filter((ro) => ro.type === RouteObjectType.Point)}
                      />
                    )}
                  </div>
                </section>
              </A4Page>
            );
          })}
      </PohContainer>
    </Page>
  );
};

export default HikingRouteInfoPage;
