/* eslint-disable @typescript-eslint/ban-ts-comment */
import React from 'react';

import clsx from 'clsx';
import * as L from 'leaflet';

import '../../lib/leaflet-distance-markers/leaflet-distance-marker';
import '../../lib/leaflet-distance-markers/leaflet-distance-marker.css';

import { watermarkToMap } from '@apps/Routes/@helpers/addToMap.helper';
import getColor from '@helpers/colorsHelper';
import { getForestTileLayer, getMap, quadkey } from '@helpers/leafletHelper';

import '@raruto/leaflet-elevation';
import '@raruto/leaflet-elevation/dist/leaflet-elevation.min.css';

import styles from './styles.module.less';

interface IMapWithElevationProps extends React.HTMLAttributes<HTMLDivElement> {
  points?: Array<number[]>;
  pointsSet?: Array<number[]>[];
  mapType?: {
    tileUrlTmpl: string;
  };
  url?: string;
  height?: number;
  slope?: boolean;
}

const MapWithElevation: React.FC<IMapWithElevationProps> = ({
  points,
  pointsSet,
  height = 300,
  slope = false,
  mapType,
  url = undefined,
  ...anotherProps
}) => {
  const containerRef = React.useRef<HTMLDivElement>(null);
  const mapRef = React.useRef<L.Map>(undefined);
  const controlElevationRef = React.useRef<any>(undefined);

  React.useEffect(() => {
    if (!containerRef.current) return;

    mapRef.current = getMap(containerRef.current, { preferCanvas: true });

    if (!mapType || window.location.hash) {
      getForestTileLayer().addTo(mapRef.current);
    } else {
      // @ts-ignore
      L.tileLayer(mapType.tileUrlTmpl, L.Util.extend({ quadkey }, mapType)).addTo(mapRef.current);
    }

    watermarkToMap(mapRef.current);

    // const mylocale = {
    //   Acceleration: 'Ускорение',
    //   Altitude: 'Высота',
    //   Slope: 'Уклон',
    //   Speed: 'Скорость',
    //   'Total Length: ': 'Дистанция ',
    //   'Max Elevation: ': 'Макс высота: ',
    //   'Min Elevation: ': 'Мин высота: ',
    //   'Total Time: ': 'Общ время: ',
    //   'Total Ascent: ': 'Набор: ',
    //   'Total Descent: ': 'Сброс: ',
    //   'Min Slope: ': 'Мин уклон: ',
    //   'Max Slope: ': 'Макс уклон: ',
    //   'Min Speed: ': 'Мин скорость: ',
    //   'Max Speed: ': 'Макс скорость: ',
    //   'Avg Speed: ': 'Средн скорость: ',
    //   'Min Acceleration: ': 'Мин ускорение: ',
    //   'Max Acceleration: ': 'Макс ускорение: ',
    //   'Avg Acceleration: ': 'Средн ускорение: ',
    //   '—': '/',
    // };

    // @ts-ignore
    //L.registerLocale('ru', mylocale);
    // @ts-ignore
    //L.setLocale('ru');

    // @ts-ignore
    controlElevationRef.current = L.control.elevation({
      // elevationDiv: '#elevation-div',
      theme: 'lightblue-theme',
      collapsed: false,
      autohide: false,
      autofitBounds: true,
      position: 'bottomleft',
      detached: true,
      summary: 'inline',
      imperial: false,
      // altitude: "disabled",
      slope: slope === undefined ? 'disabled' : slope,
      speed: false,
      acceleration: false,
      //time: true,
      legend: true,
      followMarker: true,
      almostOver: true,
      distanceMarkers: true,
      distance: true,
      preferCanvas: false,
    });

    controlElevationRef.current.addTo(mapRef.current);

    // map.scrollWheelZoom.disable();
  }, []);

  React.useEffect(() => {
    if (!controlElevationRef.current) return;
    if (!mapRef.current) return;

    const boundCoordinates: Array<number[]> = [];

    if (points) {
      boundCoordinates.push(...points);

      const pl = new L.Polyline(
        points.map((x) => [x[0], x[1]]),
        {
          color: '#ff0000',
          weight: 2,
          opacity: 1,
        },
      );

      pl.addTo(mapRef.current);

      // @ts-ignore
      const geoJSON = {
        name: 'track.geojson',
        type: 'FeatureCollection',
        features: [
          {
            type: 'Feature',
            geometry: {
              type: 'LineString',
              coordinates: [...points.map(([lat, lon, alt]) => [lon, lat, alt])],
            },
            properties: null,
          },
        ],
      };
      controlElevationRef.current.load(JSON.stringify(geoJSON));
    } else if (pointsSet) {
      pointsSet.forEach((p, i) => {
        boundCoordinates.push(...p);
        if (p && mapRef.current) {
          const pl = new L.Polyline(
            p.map((x) => [x[0], x[1]]),
            {
              color: getColor(i),
              weight: 2,
              opacity: 1,
            },
          );

          pl.addTo(mapRef.current);
        }
      });

      const geoJSON = {
        name: 'track.geojson',
        type: 'FeatureCollection',
        features: pointsSet.map((ps) => {
          return {
            type: 'Feature',
            geometry: {
              type: 'LineString',
              coordinates: [...ps.map(([lat, lon, alt]) => [lon, lat, alt])],
            },
            properties: null,
          };
        }),
      };

      controlElevationRef.current.load(JSON.stringify(geoJSON));
    }

    // @ts-ignore
    const bounds = L.latLngBounds(boundCoordinates);
    if (bounds.isValid()) {
      mapRef.current && mapRef.current.fitBounds(bounds);
    }
  }, [points, url, pointsSet]);

  // @ts-ignore
  return (
    <div
      ref={containerRef}
      {...anotherProps}
      className={clsx(anotherProps?.className, styles.mapEle)}
      style={{ height: height, ...(anotherProps?.style || {}) }}
    />
  );
};

export default MapWithElevation;
